import os, pathlib, subprocess, sys
import pytest

REQ = pathlib.Path(__file__).resolve().parents[1]
ROOT = REQ.parent
DEMO = REQ / "demo"
# REALITY_REQ_SRC lets tools/mutate.py test a mutated copy of the source instead of this tree
for p in (os.environ.get("REALITY_REQ_SRC") or REQ / "src", ROOT / "v4" / "src"):
    if str(p) not in sys.path:
        sys.path.insert(0, str(p))


@pytest.fixture(scope="session")
def demo_data(tmp_path_factory):
    """The demo's data, regenerated by the (untrusted) producers into a temporary folder."""
    d = tmp_path_factory.mktemp("demo-data")
    subprocess.run([sys.executable, str(DEMO / "render_frames.py"), str(d)], check=True, capture_output=True)
    subprocess.run([sys.executable, str(DEMO / "make_drops.py"), str(d)], check=True, capture_output=True)
    subprocess.run([sys.executable, str(DEMO / "make_playtest.py"), str(d)], check=True, capture_output=True)
    subprocess.run([sys.executable, str(DEMO / "make_evals.py"), str(d)], check=True, capture_output=True)
    return d
